from pathlib import Path
import json
from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, KeepTogether

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'reports' / 'EdgeInspect-AI_Phase1_Technical_Report.pdf'
BLUE = colors.HexColor('#123B5D')
TEAL = colors.HexColor('#137C8B')
INK = colors.HexColor('#1E293B')
MUTED = colors.HexColor('#526174')

def footer(canvas, doc):
    canvas.saveState()
    canvas.setStrokeColor(colors.HexColor('#D7E0E8'))
    canvas.line(16*mm, 14*mm, 194*mm, 14*mm)
    canvas.setFont('Helvetica', 8)
    canvas.setFillColor(MUTED)
    canvas.drawString(16*mm, 9*mm, 'EdgeInspect-AI | Final project report | 24 Nov 2026')
    canvas.drawRightString(194*mm, 9*mm, f'Page {doc.page}')
    canvas.restoreState()

def para(text, style):
    return Paragraph(text.replace('&','&amp;'), style)

def main():
    s = getSampleStyleSheet()
    s.add(ParagraphStyle(name='Deck2', parent=s['Normal'], alignment=TA_CENTER, fontSize=10, leading=15, textColor=MUTED, spaceAfter=5))
    s.add(ParagraphStyle(name='H2x', parent=s['Heading2'], fontSize=13, leading=16, textColor=BLUE, spaceBefore=8, spaceAfter=4, keepWithNext=True))
    s.add(ParagraphStyle(name='H3x', parent=s['Heading3'], fontSize=10, leading=13, textColor=TEAL, spaceBefore=5, spaceAfter=3, keepWithNext=True))
    s.add(ParagraphStyle(name='Bodyx', parent=s['BodyText'], fontSize=8.7, leading=12, textColor=INK, spaceAfter=5))
    s.add(ParagraphStyle(name='Smallx', parent=s['BodyText'], fontSize=7.4, leading=10, textColor=MUTED, spaceAfter=3))
    s.add(ParagraphStyle(name='Cellx', parent=s['BodyText'], fontSize=7.2, leading=9, textColor=INK, spaceAfter=0))
    s.add(ParagraphStyle(name='CellHeadx', parent=s['BodyText'], fontSize=7.2, leading=9, textColor=colors.white, fontName='Helvetica-Bold', spaceAfter=0))
    doc = SimpleDocTemplate(str(OUT), pagesize=A4, rightMargin=16*mm, leftMargin=16*mm, topMargin=14*mm, bottomMargin=19*mm, title='EdgeInspect-AI Final Project Report - Phase 1', author='EdgeInspect-AI Project Team', subject='Bharat AI-SoC Challenge 2026-27 PS5')
    story=[]
    story += [Spacer(1,5*mm), Paragraph('EdgeInspect-AI', s['Title']), para('Final Project Report - Phase 1 · Bharat AI-SoC Challenge 2026-27 · PS5', s['Deck2']), para('<b>Prepared 24 November 2026 from saved records</b> · organizer email sets deadline 25 November 2026, 11:59 pm IST', s['Deck2']), Spacer(1,4*mm)]
    story += [Paragraph('Executive summary',s['H2x']), para('EdgeInspect-AI is a working software prototype for steel-surface inspection. It combines a YOLOv8n detector trained on NEU-DET, a local inspection dashboard, rule-based severity and quality-control guidance, QR/barcode reading, and inspection history. Laptop model evaluation is documented. A small CPU inference smoke run was recorded on the AMD Kria KV260.',s['Bodyx']), para('<b>Integration status:</b> this is not a completed end-to-end target-hardware integration. Llama 3.2 1B was exported to ExecuTorch and smoke-run on the Windows laptop CPU, but has not been deployed to an Arm board. The KV260 result is CPU-only; FPGA/DPU acceleration has not been run. Renesas firmware has not been built or tested on the board.',s['Bodyx']), Paragraph('System and data',s['H2x']), para('Selected detector: <b>YOLOv8n, EXP-002, 320 × 320 input</b>, trained for 100 epochs on six NEU-DET steel defect classes. The prepared dataset has 1,799 images after removal of one exact duplicate: 1,259 train, 270 validation, and 270 test images. Dataset files are not included in the upload copy.',s['Bodyx']), para('The model is specialized for these steel images. Results do not establish performance on bottles, PCBs, or arbitrary products. False detections on unrelated scenes have been observed, so predictions require human review.',s['Bodyx']), Paragraph('Methodology',s['H2x']), para('The preparation script removes corrupt files and exact duplicates, validates Pascal VOC XML boxes, converts boxes to normalized YOLO labels, and makes a stratified 70/15/15 train/validation/test split with seed 42. The test split was held out for the saved evaluations. Training used COCO-pretrained YOLOv8n/YOLO11n. EXP-002 used 320-pixel input, 100 epochs, batch 16, SGD with learning rate 0.01, momentum 0.937, weight decay 0.0005, deterministic seed 42, patience 25, and brightness/translation/scale/flips/mosaic augmentation; mosaic closed for the final 10 epochs.',s['Bodyx']), Paragraph('Recorded detector results',s['H2x'])]
    vals=[('EXP-001','YOLOv8n / 640','0.6732','0.7478','0.7724','0.4307','92.28 ms / 10.8'),('EXP-002 selected','YOLOv8n / 320','0.7118','0.7093','0.7702','0.4361','36.65 ms / 27.3'),('EXP-003','YOLO11n / 640','0.7244','0.7186','0.7715','0.4327','93.10 ms / 10.7')]
    head=['Run','Model / input','P','R','mAP50','mAP50-95','Laptop total / FPS']
    rows=[[para(x,s['CellHeadx']) for x in head]]+[[para(x,s['Cellx']) for x in row] for row in vals]
    t=Table(rows, colWidths=[28*mm,35*mm,13*mm,13*mm,18*mm,23*mm,37*mm], repeatRows=1, hAlign='LEFT')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),BLUE),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F0F5F8')]),('GRID',(0,0),(-1,-1),0.4,colors.HexColor('#C9D4DE')),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('LEFTPADDING',(0,0),(-1,-1),4),('RIGHTPADDING',(0,0),(-1,-1),4),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5)]))
    story += [t,Spacer(1,2*mm),para('All scores are recorded measurements on the same 270-image held-out NEU-DET test split. EXP-002 was selected for the laptop prototype because it retained similar test scores with lower recorded laptop latency. Its weakest per-class AP50 values are crazing (0.4433) and rolled-in scale (0.5510). These are not board accuracy claims. Separate EXP-002 FP32 ONNX evaluation: mAP50 0.7559 and mAP50-95 0.4208.',s['Smallx']),Paragraph('Hardware utilization and optimization',s['H2x']),para('Training environment records identify Tesla T4 GPUs on Kaggle. Local dashboard and benchmark runs used the Windows Intel Core i5-13420H CPU. Kria KV260 has a saved six-image CPU smoke record only; no FPGA/DPU or camera path was measured. Llama + ExecuTorch has a laptop CPU smoke record only. Renesas board firmware/UART was not physically validated.',s['Bodyx']),para('The 320-pixel setting recorded 36.65 ms total per image on the laptop versus 92.28 ms for the 640-pixel YOLOv8n run, with test mAP50 0.7702 versus 0.7724. YOLO11n at 640 pixels was a comparison. FP32 ONNX scored mAP50 0.7559 / mAP50-95 0.4208, so PyTorch remains the dashboard model. Video processing samples frames. The laptop XNNPACK export used a quantization configuration and produced an 802,035,968-byte artifact; target-device speed, RAM, power, and accuracy gains have not been measured.',s['Bodyx']),PageBreak()]
    story += [Paragraph('Application and demo',s['H2x']),para('The Windows Gradio app supports still images, webcam capture, and sampled video; it displays numbered candidate detections, rule-based severity/QC recommendations, and a local inspection log. QR/barcode decoding is separate. The public static browser demo provides photo/video input, live camera sampling, QR/barcode reading, built-in samples, and browser-local history. Its inference runs in the visitor’s browser; it is not connected to a live Kria or Renesas service.',s['Bodyx']),para('<b>Public browser demo:</b> https://katyayanivlsi-edgeinspect-ai-live.static.hf.space/index.html<br/><b>Project status site:</b> https://katyayanitiwari.github.io/edgeinspect-ai-site/<br/><b>Source project reference:</b> https://github.com/katyayanitiwari/EdgeInspect-AI-code',s['Bodyx']),para('Project records say the links responded on 13 November 2026; recheck before submission. A two-minute captioned walkthrough has been assembled at demo/EdgeInspect-AI-Phase1-Demo.mp4 from actual model outputs and project assets. It is not a live desktop capture or voiceover. Review it and upload it publicly to YouTube/Google Drive; organizer preferences are 1080p, 16:9, MP4. A public GitHub/GitLab repository is required and mentor review is recommended.',s['Bodyx']),Paragraph('Edge and language-model status',s['H2x']),Paragraph('Laptop ExecuTorch',s['H3x']),para('The private local status record says the authorized Llama 3.2 1B Instruct files were downloaded, ExecuTorch 1.6 CPU/XNNPACK created an 802,035,968-byte .pte, and a laptop CPU smoke run loaded it and generated tokens. This verifies a local software path only. A later re-export attempt ended with a Windows WinError 2, so export reproducibility still needs fixing. Output relevance needs further review. Private model and runtime files are excluded from this report package and must not be uploaded.',s['Bodyx']),Paragraph('Kria KV260 CPU',s['H3x']),para('The saved smoke record reports six held-out NEU-DET images at 320 px, median model.predict latency 762.571 ms/image and mean 764.019 ms/image (about 1.311 images/s). It used CPU inference, one excluded warm-up, and three timed repeats per image. This is a small smoke test, not a robust accuracy benchmark. No FPGA/DPU inference, camera capture, power measurement, or full live pipeline has been verified.',s['Bodyx']),Paragraph('Renesas',s['H3x']),para('UART protocol and firmware template files exist. The exact board variant and pin route have not been confirmed in the project evidence. Firmware build, flash, and physical request/response exchange are not verified.',s['Bodyx']),Paragraph('Completion matrix',s['H2x'])]
    matrix=[['Area','Evidence-backed state','Remaining validation'],['NEU-DET detector','Three 100-epoch runs; saved held-out metrics','Error examples and broader validation'],['Laptop dashboard','Image/video/webcam workflow; local history code','Review prepared walkthrough and publish it'],['QR/barcode','Reader feature and samples in app','Show a clear decoded result if the demo/form requires it'],['Public browser demo','Static hosted demo URL documented','Recheck link and browser permissions'],['Llama + ExecuTorch','Laptop .pte export and CPU smoke recorded','Review outputs; compatible Arm runtime'],['Kria KV260','CPU smoke on six images recorded','Repeatable benchmark; camera/API; FPGA/DPU'],['Renesas UART','Protocol and source template prepared','Identify board; build, flash, physical test'],['Offline end-to-end','Local components exist','Verify complete disconnected target pipeline']]
    rows=[[para(x,s['CellHeadx']) for x in matrix[0]]]+[[para(x,s['Cellx']) for x in row] for row in matrix[1:]]
    t=Table(rows,colWidths=[34*mm,67*mm,66*mm],repeatRows=1)
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),BLUE),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F0F5F8')]),('GRID',(0,0),(-1,-1),0.35,colors.HexColor('#C9D4DE')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),4),('RIGHTPADDING',(0,0),(-1,-1),4),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4)]))
    story += [t,PageBreak(),Paragraph('Before submission',s['H2x'])]
    steps=[('1. Review and publish the prepared demo video.','Open demo/EdgeInspect-AI-Phase1-Demo.mp4. It is a two-minute captioned asset-based walkthrough, not live desktop capture or voiceover. If acceptable, upload publicly to YouTube/Google Drive and copy its URL.'),('2. Verify public GitHub/GitLab repository and demo links; mentor review is recommended.','Confirm the site opens, browser camera permission works, and the submission form’s exact file/format rules.'),('3. Submit the public repository URL, public demo video URL, and this final report in the designated form. Submit only once.','Include source, application/demo instructions, this report, and the requested video. Exclude LOCAL_ONLY_DO_NOT_UPLOAD, tokens, personal notes, user inspection logs, and gated model files.'),('4. Upgrade claims only with new evidence.','If board time allows, save logs and measurements for fresh Kria/Renesas runs before changing an item from “not verified.”')]
    for h,b in steps: story.append(KeepTogether([Paragraph(h,s['H3x']),para(b,s['Bodyx'])]))
    story += [Paragraph('Evidence and references',s['H2x']),para('Project records: README.md; CHALLENGE.md; evaluation/EXP-001/metrics.json, EXP-002/metrics.json, EXP-003/metrics.json; evaluation/EXP-002/ERROR_ANALYSIS.md; deployment/kv260/kv260_cpu_smoke_summary.json; docs/IMPLEMENTATION_STATUS.md; private local LOCAL_ONLY_DO_NOT_UPLOAD/LLAMA_EXECUTORCH_STATUS.md (status evidence only; do not distribute private model files).',s['Smallx']),para('Official challenge page: https://arm-education.github.io/Arm-Developer-Labs/Bharat_AI_SoC_2026_27.html . It lists source code, an application, a technical report, and a demonstration video for Phase 1. Recheck the page and submission form for changes.',s['Smallx']),Spacer(1,2*mm),para('<b>Reporting note:</b> “exported and smoke-run on laptop” is not the same as “deployed and integrated on target hardware.” This report uses the narrower, evidence-supported wording.',s['Smallx'])]
    doc.build(story,onFirstPage=footer,onLaterPages=footer)
    print(OUT)

if __name__=='__main__': main()
